/* ---------------- Spanish (Stage 6). One language is one file like this; src/lang.js explains how it is used. ----------------
   words: a whole English line, or one part of a line between " · ", with its Spanish.
   rules: the same for lines with a number or a name in them. The first rule that fits wins; a rule that answers null is passed over.
   help:  the Help page's answers, by topic id (src/helpdata.js has the English). A button named in **bold** keeps its English name
          when its screen is still in English, so it can be found.
   Covered so far: the sidebar, Today, the welcome, Find anything, Help, and the feedback page in a returned paper. */
const ES_NUM = { no: 0, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12 };
const ES_WORD = ['ningún', 'un', 'dos', 'tres', 'cuatro', 'cinco', 'seis', 'siete', 'ocho', 'nueve', 'diez', 'once', 'doce'];
// "Two" or "12" as a number, and a number as Spanish words (f: with a feminine noun, alone: with no noun after it).
const esN = w => { const k = String(w).toLowerCase(); return k in ES_NUM ? ES_NUM[k] : +w; };
const esW = (n, f, alone) => n === 1 ? (f ? 'una' : alone ? 'uno' : 'un') : n === 0 ? (f ? 'ninguna' : alone ? 'ninguno' : 'ningún') : ES_WORD[n] || String(n);
const esCap = s => s.charAt(0).toUpperCase() + s.slice(1);
const esSets = n => esW(n) + (n === 1 ? ' grupo' : ' grupos') + ' de trabajos';
// The line under Today's date: what she teaches, then what is waiting.
function esHomeSay(k) {
  const m = /^(?:(No classes today\.|(\w+) class(?:es)? today\.) ?)?(.*)$/.exec(k); if (!m) return null;
  let teach = '', work = '';
  if (m[1]) teach = m[2] ? (esN(m[2]) === 1 ? 'Una clase hoy.' : esCap(esW(esN(m[2]), true)) + ' clases hoy.') : 'Hoy no hay clases.';
  const w = m[3];
  let x;
  if (!w) work = '';
  else if ((x = /^(\w+) sets? of papers to mark, (\w+) ready to hand back\.$/i.exec(w))) work = esSets(esN(x[1])) + ' por corregir y ' + esW(esN(x[2]), false, true) + (esN(x[2]) === 1 ? ' listo' : ' listos') + ' para devolver.';
  else if ((x = /^(\w+) sets? of papers to mark\.$/i.exec(w))) work = esSets(esN(x[1])) + ' por corregir.';
  else if ((x = /^(\w+) sets? of papers ready to hand back\.$/i.exec(w))) work = esSets(esN(x[1])) + (esN(x[1]) === 1 ? ' listo' : ' listos') + ' para devolver.';
  else if (/^nothing waiting to be marked\.$/i.test(w)) work = 'nada por corregir.';
  else return null;
  if (!teach && !work) return null;
  return (teach + (work ? (teach ? ' ' : '') + esCap(work) : '')).trim();
}
